-- POSTGRESQL 18 SCHEMA & DATA MIGRATION SCRIPT
-- Source: D:\ProjectsWorkSpace\LeaderShipAsscement\Database\UpdatedDBforMigration.sql
-- Target Database: PostgreSQL 18 (Local & Cloud Compatible)
-- Database Name: leadership_assesment
-- ============================================================================

-- Set connection parameters
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET client_min_messages = warning;
SET row_security = off;

-- ----------------------------------------------------------------------------
-- 1. DROP EXISTING TABLES (Local Disposable Clean Setup)
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS assessment_submissions CASCADE;
DROP TABLE IF EXISTS assessment_drafts CASCADE;
DROP TABLE IF EXISTS assessment_public_submissions CASCADE;
DROP TABLE IF EXISTS file_upload_history CASCADE;
DROP TABLE IF EXISTS admin_blocked_slots CASCADE;
DROP TABLE IF EXISTS admin_shift_config CASCADE;
DROP TABLE IF EXISTS admin_slot_config CASCADE;
DROP TABLE IF EXISTS respondent CASCADE;

-- ----------------------------------------------------------------------------
-- 2. CREATE MASTER / CANONICAL TABLE: respondent
-- ----------------------------------------------------------------------------
CREATE TABLE respondent (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    firstname VARCHAR(512) NOT NULL,
    lastname VARCHAR(512) DEFAULT NULL,
    mobile VARCHAR(512) DEFAULT NULL,
    email VARCHAR(512) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    role VARCHAR(30) DEFAULT 'Respondent' CHECK (role IN ('Admin', 'Leadership', 'Respondent')),
    status VARCHAR(20) DEFAULT 'Active' CHECK (status IN ('Active', 'Inactive')),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    email_hash CHAR(64) DEFAULT NULL,
    mobile_hash CHAR(64) DEFAULT NULL
);

CREATE INDEX idx_respondent_email_hash ON respondent (email_hash);
CREATE INDEX idx_respondent_mobile_hash ON respondent (mobile_hash);

-- ----------------------------------------------------------------------------
-- 3. CREATE CONFIGURATION & SUPPORTING TABLES
-- ----------------------------------------------------------------------------

-- Table: admin_blocked_slots
CREATE TABLE admin_blocked_slots (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    block_date VARCHAR(50) NOT NULL,
    slot_time VARCHAR(20) DEFAULT NULL,
    reason VARCHAR(255) DEFAULT NULL,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: admin_shift_config
CREATE TABLE admin_shift_config (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shift_type VARCHAR(100) NOT NULL,
    start_time VARCHAR(20) NOT NULL,
    end_time VARCHAR(20) NOT NULL,
    max_capacity INT DEFAULT 15,
    call_duration_mins INT DEFAULT 20,
    grace_period_mins INT DEFAULT 10,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: admin_slot_config
CREATE TABLE admin_slot_config (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slot_time VARCHAR(20) NOT NULL UNIQUE,
    is_active BOOLEAN DEFAULT TRUE,
    display_order INT DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Table: file_upload_history
CREATE TABLE file_upload_history (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    file_name VARCHAR(255) NOT NULL,
    original_file_name VARCHAR(255) NOT NULL,
    uploaded_by INT NOT NULL,
    uploaded_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    file_path VARCHAR(500) DEFAULT NULL,
    file_size BIGINT DEFAULT NULL,
    status VARCHAR(20) DEFAULT 'Active' CHECK (status IN ('Active', 'Archived')),
    CONSTRAINT fk_file_upload_respondent FOREIGN KEY (uploaded_by) REFERENCES respondent (id)
);

CREATE INDEX idx_file_upload_uploaded_by ON file_upload_history (uploaded_by);

-- ----------------------------------------------------------------------------
-- 4. CREATE ASSESSMENT & DRAFT TABLES (Strict Respondent Normalization)
-- ----------------------------------------------------------------------------

-- Table: assessment_drafts
CREATE TABLE assessment_drafts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    respondent_id INT NOT NULL,
    assessment_type VARCHAR(100) NOT NULL DEFAULT 'leadership_reset',
    answered_count INT NOT NULL DEFAULT 0,
    draft_payload JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    reminder_sent_at TIMESTAMPTZ DEFAULT NULL,
    reminder_attempts INT NOT NULL DEFAULT 0,
    reminder_last_error VARCHAR(500) DEFAULT NULL,
    CONSTRAINT uq_assessment_drafts_user_type UNIQUE (respondent_id, assessment_type),
    CONSTRAINT fk_drafts_respondent FOREIGN KEY (respondent_id) REFERENCES respondent (id)
);

CREATE INDEX idx_assessment_drafts_updated_at ON assessment_drafts (updated_at);

-- Table: assessment_submissions
CREATE TABLE assessment_submissions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    respondent_id INT NOT NULL,
    assessment_type VARCHAR(80) NOT NULL,
    submitted_at TIMESTAMPTZ DEFAULT NULL,
    total_score NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
    total_weighted_score NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
    submission_payload TEXT DEFAULT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status VARCHAR(20) NOT NULL DEFAULT 'Active',
    CONSTRAINT uq_submission_once UNIQUE (respondent_id, assessment_type),
    CONSTRAINT fk_submissions_respondent FOREIGN KEY (respondent_id) REFERENCES respondent (id)
);

CREATE INDEX idx_submission_created_at ON assessment_submissions (created_at);

-- Table: assessment_public_submissions
CREATE TABLE assessment_public_submissions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    assessment_type VARCHAR(80) NOT NULL,
    first_name VARCHAR(120) DEFAULT NULL,
    last_name VARCHAR(120) DEFAULT NULL,
    email VARCHAR(255) DEFAULT NULL,
    mobile VARCHAR(32) DEFAULT NULL,
    submitted_at TIMESTAMPTZ DEFAULT NULL,
    total_score NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
    total_weighted_score NUMERIC(12, 2) NOT NULL DEFAULT 0.00,
    submission_payload TEXT DEFAULT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_public_submissions_email ON assessment_public_submissions (email);
CREATE INDEX idx_public_submissions_created_at ON assessment_public_submissions (created_at);

