(37912104, 3300005, 'leadership_reset', 12, '{"savedAt": "2026-09-16T13:07:29.411Z", "totalScore": 23, "answersByRow": {"6": "A. It varies — different people lead depending on the topic", "7": "A. There wasn''t really an opportunity to raise it", "8": "A. We move fast — sometimes too fast", "9": "A. Yes — several people", "12": "A. A wide range of people — challenge is distributed", "13": "A. The challenge is taken seriously and explored", "14": "A. Yes — a few clear ones", "15": "A. Yes — fairly regularly", "18": "A. The conversation converges toward my view fairly quickly", "19": "A. Mostly the most knowledgeable — they tend to be heard", "20": "A. I call it — make the decision and move on", "21": "A. More people contributing their thinking earlier"}, "respondentId": 3300005, "answeredCount": 12, "totalQuestions": 12, "questionResponses": [{"score": 4, "answer": "A. It varies — different people lead depending on the topic", "number": 1, "weight": 2, "section": "DECISION MAKING", "question": "When your team discusses a decision, who typically speaks first?", "rowIndex": 6, "weightedScore": 8}, {"score": 1, "answer": "A. There wasn''t really an opportunity to raise it", "number": 2, "weight": 2, "section": "DECISION MAKING", "question": "Think of a recent decision where something important emerged after the fact. What do you think stopped it surfacing in the room?", "rowIndex": 7, "weightedScore": 2}, {"score": 1, "answer": "A. We move fast — sometimes too fast", "number": 3, "weight": 1, "section": "DECISION MAKING", "question": "How would you describe the pace of decisions in your leadership meetings?", "rowIndex": 8, "weightedScore": 1}, {"score": 1, "answer": "A. Yes — several people", "number": 4, "weight": 2, "section": "DECISION MAKING", "question": "Are there people in your team you know have strong views but rarely voice them in meetings?", "rowIndex": 9, "weightedScore": 2}, {"score": 0, "answer": "A. A wide range of people — challenge is distributed", "number": 5, "weight": 2, "section": "CONVERSATION PATTERNS", "question": "Who challenges in your leadership meetings?", "rowIndex": 12, "weightedScore": 0}, {"score": 4, "answer": "A. The challenge is taken seriously and explored", "number": 6, "weight": 2, "section": "CONVERSATION PATTERNS", "question": "When someone does push back in a discussion, how does the room typically respond?", "rowIndex": 13, "weightedScore": 8}, {"score": 1, "answer": "A. Yes — a few clear ones", "number": 7, "weight": 1, "section": "CONVERSATION PATTERNS", "question": "Are there topics in your leadership discussions that feel quietly off-limits — where challenge just doesn''t happen?", "rowIndex": 14, "weightedScore": 1}, {"score": 1, "answer": "A. Yes — fairly regularly", "number": 8, "weight": 2, "section": "CONVERSATION PATTERNS", "question": "After meetings, do you hear different views from people in the corridor to what was said in the room?", "rowIndex": 15, "weightedScore": 2}, {"score": 1, "answer": "A. The conversation converges toward my view fairly quickly", "number": 9, "weight": 3, "section": "LEADER SIGNALS", "question": "When you signal your own view early in a discussion, what tends to happen?", "rowIndex": 18, "weightedScore": 3}, {"score": 4, "answer": "A. Mostly the most knowledgeable — they tend to be heard", "number": 10, "weight": 3, "section": "LEADER SIGNALS", "question": "Do you feel you hear from the people with the most relevant knowledge, or those most comfortable speaking?", "rowIndex": 19, "weightedScore": 12}, {"score": 2, "answer": "A. I call it — make the decision and move on", "number": 11, "weight": 2, "section": "LEADER SIGNALS", "question": "When a discussion goes in circles, what is your instinct?", "rowIndex": 20, "weightedScore": 4}, {"score": 3, "answer": "A. More people contributing their thinking earlier", "number": 12, "weight": 1, "section": "LEADER SIGNALS", "question": "If you could change one thing about how your team makes complex decisions, what would it be?", "rowIndex": 21, "weightedScore": 3}], "totalWeightedScore": 46}'::jsonb, '2026-09-16 13:06:58+00', '2026-09-17 05:39:40+00', '2026-09-17 05:39:40+00', 1, NULL),
