(810001, 1140005, 'leadership_reset', '2026-07-23 11:09:28+00', 23.00, 45.00, '{"respondentId": 1140005, "submittedAt": "2026-07-23T11:09:27.926Z", "totalScore": 23, "totalWeightedScore": 45, "answersByRow": {"6": "D. I''m not sure, I haven''t noticed a pattern", "7": "A. There wasn''t really an opportunity to raise it", "8": "A. We move fast - sometimes too fast", "9": "B. One or two, yes", "12": "B. Usually the same 1–2 people", "13": "C. It creates tension - challenge feels uncomfortable", "14": "B. Maybe one or two - I haven''t thought about it much", "15": "C. Rarely or never", "18": "C. I try not to signal early - I hold back deliberately", "19": "C. A mix - it varies by topic", "20": "A. I call it - make the decision and move on", "21": "B. Faster closure - we over-discuss"}, "questionResponses": [{"rowIndex": 6, "number": 1, "section": "DECISION MAKING", "question": "When your team discusses a decision, who typically speaks first?", "answer": "D. I''m not sure, I haven''t noticed a pattern", "score": 3, "weight": 2, "weightedScore": 6}, {"rowIndex": 7, "number": 2, "section": null, "question": "Think of a recent decision where something important emerged after the fact. What do you think stopped it surfacing in the room?", "answer": "A. There wasn''t really an opportunity to raise it", "score": 1, "weight": 2, "weightedScore": 2}, {"rowIndex": 8, "number": 3, "section": null, "question": "How would you describe the pace of decisions in your leadership meetings?", "answer": "A. We move fast - sometimes too fast", "score": 1, "weight": 1, "weightedScore": 1}, {"rowIndex": 9, "number": 4, "section": null, "question": "Are there people in your team you know have strong views but rarely voice them in meetings?", "answer": "B. One or two, yes", "score": 2, "weight": 2, "weightedScore": 4}, {"rowIndex": 12, "number": 5, "section": "CONVERSATION PATTERNS", "question": "Who challenges in your leadership meetings?", "answer": "B. Usually the same 1–2 people", "score": 1, "weight": 2, "weightedScore": 2}, {"rowIndex": 13, "number": 6, "section": null, "question": "When someone does push back in a discussion, how does the room typically respond?", "answer": "C. It creates tension - challenge feels uncomfortable", "score": 1, "weight": 2, "weightedScore": 2}, {"rowIndex": 14, "number": 7, "section": null, "question": "Are there topics in your leadership discussions that feel quietly off-limits — where challenge just doesn''t happen?", "answer": "B. Maybe one or two - I haven''t thought about it much", "score": 2, "weight": 1, "weightedScore": 2}, {"rowIndex": 15, "number": 8, "section": null, "question": "After meetings, do you hear different views from people in the corridor to what was said in the room?", "answer": "C. Rarely or never", "score": 4, "weight": 2, "weightedScore": 8}, {"rowIndex": 18, "number": 9, "section": "LEADER SIGNALS", "question": "When you signal your own view early in a discussion, what tends to happen?", "answer": "C. I try not to signal early - I hold back deliberately", "score": 4, "weight": 3, "weightedScore": 12}, {"rowIndex": 19, "number": 10, "section": null, "question": "Do you feel you hear from the people with the most relevant knowledge, or those most comfortable speaking?", "answer": "C. A mix - it varies by topic", "score": 0, "weight": 3, "weightedScore": 0}, {"rowIndex": 20, "number": 11, "section": null, "question": "When a discussion goes in circles, what is your instinct?", "answer": "A. I call it - make the decision and move on", "score": 2, "weight": 2, "weightedScore": 4}, {"rowIndex": 21, "number": 12, "section": null, "question": "If you could change one thing about how your team makes complex decisions, what would it be?", "answer": "B. Faster closure - we over-discuss", "score": 2, "weight": 1, "weightedScore": 2}]}', '2026-07-23 11:09:34+00', 'Active'),
(900001, 1350005, 'leadership_reset', '2026-07-27 14:27:04+00', 16.00, 36.00, '{"respondentId": 1350005, "submittedAt": "2026-07-27T14:27:04.413Z", "totalScore": 16, "totalWeightedScore": 36, "answersByRow": {"6": "C. The same 1–2 people, regardless of topic", "7": "B. The person who knew held back, I''m not sure why", "8": "D. Decisions often drift without a clear close", "9": "D. I''m honestly not sure", "12": "B. Usually the same 1–2 people", "13": "C. It creates tension - challenge feels uncomfortable", "14": "A. Yes - a few clear ones", "15": "D. I''m not sure - it doesn''t come to my attention", "18": "C. I try not to signal early - I hold back deliberately", "19": "B. Honestly, more often the most comfortable speakers", "20": "D. I escalate or defer to a smaller group", "21": "C. Better challenge - views go untested"}, "questionResponses": [{"rowIndex": 6, "number": 1, "section": "DECISION MAKING", "question": "When your team discusses a decision, who typically speaks first?", "answer": "C. The same 1–2 people, regardless of topic", "score": 1, "weight": 2, "weightedScore": 2}, {"rowIndex": 7, "number": 2, "section": null, "question": "Think of a recent decision where something important emerged after the fact. What do you think stopped it surfacing in the room?", "answer": "B. The person who knew held back, I''m not sure why", "score": 2, "weight": 2, "weightedScore": 4}, {"rowIndex": 8, "number": 3, "section": null, "question": "How would you describe the pace of decisions in your leadership meetings?", "answer": "D. Decisions often drift without a clear close", "score": 0, "weight": 1, "weightedScore": 0}, {"rowIndex": 9, "number": 4, "section": null, "question": "Are there people in your team you know have strong views but rarely voice them in meetings?", "answer": "D. I''m honestly not sure", "score": 2, "weight": 2, "weightedScore": 4}, {"rowIndex": 12, "number": 5, "section": "CONVERSATION PATTERNS", "question": "Who challenges in your leadership meetings?", "answer": "B. Usually the same 1–2 people", "score": 1, "weight": 2, "weightedScore": 2}, {"rowIndex": 13, "number": 6, "section": null, "question": "When someone does push back in a discussion, how does the room typically respond?", "answer": "C. It creates tension - challenge feels uncomfortable", "score": 1, "weight": 2, "weightedScore": 2}, {"rowIndex": 14, "number": 7, "section": null, "question": "Are there topics in your leadership discussions that feel quietly off-limits — where challenge just doesn''t happen?", "answer": "A. Yes - a few clear ones", "score": 1, "weight": 1, "weightedScore": 1}, {"rowIndex": 15, "number": 8, "section": null, "question": "After meetings, do you hear different views from people in the corridor to what was said in the room?", "answer": "D. I''m not sure - it doesn''t come to my attention", "score": 2, "weight": 2, "weightedScore": 4}, {"rowIndex": 18, "number": 9, "section": "LEADER SIGNALS", "question": "When you signal your own view early in a discussion, what tends to happen?", "answer": "C. I try not to signal early - I hold back deliberately", "score": 4, "weight": 3, "weightedScore": 12}, {"rowIndex": 19, "number": 10, "section": null, "question": "Do you feel you hear from the people with the most relevant knowledge, or those most comfortable speaking?", "answer": "B. Honestly, more often the most comfortable speakers", "score": 1, "weight": 3, "weightedScore": 3}, {"rowIndex": 20, "number": 11, "section": null, "question": "When a discussion goes in circles, what is your instinct?", "answer": "D. I escalate or defer to a smaller group", "score": 1, "weight": 2, "weightedScore": 2}, {"rowIndex": 21, "number": 12, "section": null, "question": "If you could change one thing about how your team makes complex decisions, what would it be?", "answer": "C. Better challenge - views go untested", "score": 0, "weight": 1, "weightedScore": 0}]}', '2026-07-27 14:27:09+00', 'Active'),
(1320002, 1710006, 'leadership_reset', '2026-08-03 09:01:38+00', 32.00, 63.00, '{"respondentId": 1710006, "submittedAt": "2026-08-03T09:01:37.588Z", "totalScore": 32, "totalWeightedScore": 63, "answersByRow": {"6": "A. It varies - different people lead depending on the topic", "7": "B. The person who knew held back, I''m not sure why", "8": "B. We sometimes revisit decisions that should have been settled", "9": "C. Not really - people speak up if they have something to say", "12": "C. Rarely anyone - we tend to align fairly quickly", "13": "A. The challenge is taken seriously and explored", "14": "B. Maybe one or two - I haven''t thought about it much", "15": "B. Occasionally", "18": "B. People still push back and explore alternatives", "19": "B. Honestly, more often the most comfortable speakers", "20": "B. I try to surface what''s blocking the conversation first", "21": "B. Faster closure - we over-discuss"}, "questionResponses": [{"rowIndex": 6, "number": 1, "section": "DECISION MAKING", "question": "When your team discusses a decision, who typically speaks first?", "answer": "A. It varies - different people lead depending on the topic", "score": 4, "weight": 2, "weightedScore": 8}, {"rowIndex": 7, "number": 2, "section": null, "question": "Think of a recent decision where something important emerged after the fact. What do you think stopped it surfacing in the room?", "answer": "B. The person who knew held back, I''m not sure why", "score": 2, "weight": 2, "weightedScore": 4}, {"rowIndex": 8, "number": 3, "section": null, "question": "How would you describe the pace of decisions in your leadership meetings?", "answer": "B. We sometimes revisit decisions that should have been settled", "score": 2, "weight": 1, "weightedScore": 2}, {"rowIndex": 9, "number": 4, "section": null, "question": "Are there people in your team you know have strong views but rarely voice them in meetings?", "answer": "C. Not really - people speak up if they have something to say", "score": 4, "weight": 2, "weightedScore": 8}, {"rowIndex": 12, "number": 5, "section": "CONVERSATION PATTERNS", "question": "Who challenges in your leadership meetings?", "answer": "C. Rarely anyone - we tend to align fairly quickly", "score": 1, "weight": 2, "weightedScore": 2}, {"rowIndex": 13, "number": 6, "section": null, "question": "When someone does push back in a discussion, how does the room typically respond?", "answer": "A. The challenge is taken seriously and explored", "score": 4, "weight": 2, "weightedScore": 8}, {"rowIndex": 14, "number": 7, "section": null, "question": "Are there topics in your leadership discussions that feel quietly off-limits — where challenge just doesn''t happen?", "answer": "B. Maybe one or two - I haven''t thought about it much", "score": 2, "weight": 1, "weightedScore": 2}, {"rowIndex": 15, "number": 8, "section": null, "question": "After meetings, do you hear different views from people in the corridor to what was said in the room?", "answer": "B. Occasionally", "score": 2, "weight": 2, "weightedScore": 4}, {"rowIndex": 18, "number": 9, "section": "LEADER SIGNALS", "question": "When you signal your own view early in a discussion, what tends to happen?", "answer": "B. People still push back and explore alternatives", "score": 4, "weight": 3, "weightedScore": 12}, {"rowIndex": 19, "number": 10, "section": null, "question": "Do you feel you hear from the people with the most relevant knowledge, or those most comfortable speaking?", "answer": "B. Honestly, more often the most comfortable speakers", "score": 1, "weight": 3, "weightedScore": 3}, {"rowIndex": 20, "number": 11, "section": null, "question": "When a discussion goes in circles, what is your instinct?", "answer": "B. I try to surface what''s blocking the conversation first", "score": 4, "weight": 2, "weightedScore": 8}, {"rowIndex": 21, "number": 12, "section": null, "question": "If you could change one thing about how your team makes complex decisions, what would it be?", "answer": "B. Faster closure - we over-discuss", "score": 2, "weight": 1, "weightedScore": 2}]}', '2026-08-03 09:01:42+00', 'Active'),
