-- ----------------------------------------------------------------------------
-- 7. POST-MIGRATION VALIDATION QUERIES
-- ----------------------------------------------------------------------------
SELECT 'TABLE ROW COUNTS:' AS report_section;

SELECT 'respondent' AS table_name, COUNT(*) AS row_count FROM respondent
UNION ALL
SELECT 'admin_blocked_slots', COUNT(*) FROM admin_blocked_slots
UNION ALL
SELECT 'admin_shift_config', COUNT(*) FROM admin_shift_config
UNION ALL
SELECT 'admin_slot_config', COUNT(*) FROM admin_slot_config
UNION ALL
SELECT 'file_upload_history', COUNT(*) FROM file_upload_history
UNION ALL
SELECT 'assessment_drafts', COUNT(*) FROM assessment_drafts
UNION ALL
SELECT 'assessment_submissions', COUNT(*) FROM assessment_submissions
UNION ALL
SELECT 'assessment_public_submissions', COUNT(*) FROM assessment_public_submissions;

SELECT 'ORPHAN CHECK (Must be 0):' AS report_section;

SELECT 'orphan_drafts' AS check_name, COUNT(*) AS orphan_count
FROM assessment_drafts d
LEFT JOIN respondent r ON r.id = d.respondent_id
WHERE r.id IS NULL
UNION ALL
SELECT 'orphan_submissions', COUNT(*)
FROM assessment_submissions s
LEFT JOIN respondent r ON r.id = s.respondent_id
WHERE r.id IS NULL
UNION ALL
SELECT 'orphan_uploads', COUNT(*)
FROM file_upload_history f
LEFT JOIN respondent r ON r.id = f.uploaded_by
WHERE r.id IS NULL;

SELECT 'POSTGRESQL 18 MIGRATION COMPLETED SUCCESSFULLY!' AS result;
